"""Build the offline review pack from the sanitized, versioned proposals only."""
import csv,html,json,pathlib,zipfile
root=pathlib.Path(__file__).resolve().parents[1]
data=json.loads((root/'resources/catalog/egypt-qatar-proposals.json').read_text())
out=root/'docs/content'; out.mkdir(exist_ok=True)
h=html.escape
fields=['academy_key','academy_name','academy_name_ar_proposed','country','city_region','sport','training_name_ar','training_name_en','proposed_price','currency','proposed_sessions','price_per_session','status','is_bookable','price_approved','logo_status','source_row','demo_coach','demo_location','start_date','end_date','weekdays','start_time','end_time','timezone','operational_details_status']
with (out/'egypt-qatar-training-proposals.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.DictWriter(f,fieldnames=fields,lineterminator='\n');w.writeheader()
    for a in data['academies']:
        for t in a['trainings']:
            values=[a['key'],a['name'],a['name_ar_proposed'],a['country'],a['city_region_from_lead'],a['sport_ar'],t['name_ar'],t['name_en'],t['proposed_price'],t['currency'],t['proposed_sessions'],t['price_per_session'],t['status'],False,False,a['logo_status'],a['lead_source_row'],a['demo_coach']['name_ar'],a['demo_location']['name_ar'],t['start_date'],t['end_date'],' / '.join(t['weekdays']),t['start_time'],t['end_time'],t['timezone'],t['operational_details_status']]
            w.writerow(dict(zip(fields,values)))
with (out/'egypt-qatar-demo-sessions.csv').open('w',encoding='utf-8-sig',newline='') as f:
    fields=['session_key','academy_name','country','training_key','training_name_ar','demo_coach','demo_location','timezone','start_at','end_at','status']
    w=csv.DictWriter(f,fieldnames=fields,lineterminator='\n');w.writeheader()
    for a in data['academies']:
        for t in a['trainings']:
            for session in t['proposed_sessions_calendar']:
                w.writerow(dict(zip(fields,[session['key'],a['name'],a['country'],t['key'],t['name_ar'],a['demo_coach']['name_ar'],a['demo_location']['name_ar'],t['timezone'],session['start_at'],session['end_at'],'demo_unverified'])))
cards=[]
for a in data['academies']:
    courses=[]
    for t in a['trainings']:
        courses.append(f'''<div class="course"><h3>{h(t['name_ar'])}</h3><div class="price">{t['proposed_price']:,} <small>{t['currency']}</small></div><div class="package">للباقة كاملة · {t['proposed_sessions']} حصص مقترحة · {t['price_per_session']:g} {t['currency']} للحصة حسابيًا</div><div class="package">مواعيد تجريبية: {h(t['weekdays_ar'])} · <span dir="ltr">{t['start_time']}–{t['end_time']}</span></div><div class="package"><span dir="ltr">{t['start_date']} → {t['end_date']}</span> · {h(t['timezone'])}</div></div>''')
    country='مصر' if a['country']=='eg' else 'قطر'
    searchable=' '.join([a['name'],a['name_ar_proposed'],a['city_region_from_lead'],a['sport_ar'],a['sport_en']]).lower()
    cards.append(f'''<article data-country="{a['country']}" data-sport="{a['selected_sport']}" data-search="{h(searchable,quote=True)}"><div class="topline"><span>{country}</span><span class="sport">{h(a['sport_ar'])}</span></div><h2>{h(a['name_ar_proposed'])}</h2><p class="original" dir="auto">{h(a['name'])}</p><p class="city" dir="auto">{h(a['city_region_from_lead'])}</p><p class="city">مدرب افتراضي: {h(a['demo_coach']['name_ar'])}</p><p class="city">موقع تجريبي: {h(a['demo_location']['name_ar'])}</p><div class="logo-status">الشعار الرسمي بانتظار التحقق</div><div class="price-label">البرامج والأسعار التالية مقترحة من حجّز وغير معتمدة من الجهة</div>{''.join(courses)}<footer>غير متاح للحجز · المواعيد والأعمار والمدرب والسعة تحتاج تأكيد الجهة</footer></article>''')
sports={a['selected_sport']:a['sport_ar'] for a in data['academies']}
options=''.join(f'<option value="{h(k,quote=True)}">{h(v)}</option>' for k,v in sorted(sports.items(),key=lambda i:i[1]))
page='''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>حجّز | مراجعة مقترحات مصر وقطر</title><style>
:root{--ink:#132630;--muted:#5e6d78;--line:#d7dfe5;--lime:#aaf448;--bg:#f3f6f7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Tahoma,Arial,sans-serif;line-height:1.7}header{background:#101b22;color:#fff;padding:38px max(24px,calc((100% - 1220px)/2)) 34px}header img{width:145px;height:55px;object-fit:contain}h1{font-size:30px;line-height:1.5;margin:18px 0 12px}header p{color:#d6e1e6;max-width:940px;margin:0;font-size:15px}.stats{display:flex;gap:10px;flex-wrap:wrap;margin-top:23px}.stats span{padding:7px 13px;border:1px solid #45534d;border-radius:8px;color:var(--lime);font-weight:bold}.wrap{max-width:1260px;margin:auto;padding:22px}.filters{display:flex;gap:12px;flex-wrap:wrap;background:#fff;border:1px solid var(--line);border-radius:12px;padding:18px;align-items:end}label{font-size:13px;color:var(--muted);display:block;margin-bottom:6px}input,select,button,.download{font:inherit;border-radius:7px;min-height:44px}input,select{border:1px solid #83909d;padding:8px 11px;background:#fff;color:var(--ink);width:100%}.field{flex:1;min-width:150px}.search{flex:2;min-width:220px}button,.download{padding:9px 14px;border:1px solid #173128;text-decoration:none;background:#173128;color:#fff;cursor:pointer;white-space:nowrap}button{background:#fff;color:#173128}.count{color:var(--muted);font-size:14px;margin:20px 2px 13px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}article{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;min-width:0;box-shadow:0 3px 12px #162b3510}article[hidden]{display:none}.topline{display:flex;justify-content:space-between;gap:8px;font-size:12px;color:var(--muted)}.sport{background:#ecf6e3;color:#2f5d1d;padding:3px 8px;border-radius:5px}h2{font-size:20px;line-height:1.6;margin:14px 0 4px}.original{font-size:13px;overflow-wrap:anywhere;color:#37566c;min-height:23px;margin:0 0 8px}.city{font-size:12px;color:var(--muted);margin:0 0 13px;min-height:22px}.logo-status{border:1px dashed #a1acb8;display:inline-block;border-radius:7px;font-size:11px;padding:4px 8px;color:#637482}.price-label{background:#fff5d7;color:#735516;font-size:11px;padding:9px;border-radius:6px;margin:16px 0 4px}.course{border-bottom:1px solid var(--line);padding:14px 0}h3{font-size:15px;line-height:1.6;font-weight:600;margin:0 0 8px}.price{font-size:25px;line-height:1.3;font-weight:bold;color:#174a31}.price small{font-size:13px}.package{font-size:11px;color:var(--muted);margin-top:6px}footer{font-size:11px;color:#566673;margin-top:14px}.empty{padding:40px;text-align:center}.notes{font-size:13px;color:var(--muted);background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;margin-top:24px}.notes h2{font-size:17px}.notes p{margin:7px 0}:focus-visible{outline:3px solid #2a66d8;outline-offset:3px}@media(max-width:1050px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.grid{grid-template-columns:1fr}.wrap{padding:14px}header{padding:24px 20px}h1{font-size:24px}.field{flex-basis:40%}.search{flex-basis:100%}article{padding:18px}}
</style></head><body><header><img src="hagzz.svg" alt="Hagzz"><h1>مقترحات أكاديميات مصر وقطر</h1><p>أسماء مختارة من ملف الليدز مع برامج وأسعار ومدربين ومواقع ومواعيد تجريبية من إعداد حجّز. هذه نسخة مراجعة داخلية، وليست إعلانًا عن شراكات أو عروض رسمية، ولا تتيح حجوزات أو مدفوعات.</p><div class="stats"><span>15 جهة في مصر</span><span>15 جهة في قطر</span><span>90 تدريبًا مقترحًا</span><span>23 رياضة</span><span>30 مدربًا افتراضيًا</span><span>600 حصة تجريبية</span></div></header><main class="wrap"><section class="filters" aria-label="تصفية المقترحات"><div class="field"><label for="country">الدولة</label><select id="country"><option value="">كل الدول</option value="eg">مصر</option><option value="qa">قطر</option></select></div><div class="field"><label for="sport">الرياضة</label><select id="sport"><option value="">كل الرياضات</option></select></div><div class="field search"><label for="query">بحث بالاسم أو المدينة</label><input id="query" type="search" placeholder="اسم الأكاديمية أو المدينة"></div><button id="reset" type="button">إعادة ضبط</button><a class="download" href="egypt-qatar-training-proposals.csv" download>تنزيل 90 مقترحًا CSV</a><a class="download" href="egypt-qatar-demo-sessions.csv" download>تنزيل مواعيد 600 حصة CSV</a></section><p class="count" id="count" role="status" aria-live="polite"></p><section class="grid" aria-label="المقترحات"></section><p class="empty" hidden>لا توجد نتائج مطابقة.</p><section class="notes"><h2>ما الذي تم التحقق منه؟</h2><p>الاسم والرياضة والمدينة نُقلت من ملف الليدز؛ لم تتحقق مطابقتها الحالية خارجيًا. الأسعار والبرامج وعدد الحصص مقترحات من حجّز، وليست أسعار الأكاديميات الرسمية.</p><p>الأسماء العربية صياغات مقترحة. المدربون أشخاص افتراضيون للتجربة، والمواقع والمواعيد غير مؤكدة من الجهات؛ لا توجد إحداثيات أو عناوين شوارع مختلقة. الأعمار والسعة غير محددتين.</p><p>تعذر الوصول إلى البحث والمواقع الخارجية من بيئة العمل بخطأ اتصال 403؛ لذلك لم نضع شعارات غير موثقة. شعار حجّز أعلى الصفحة من ملفات المشروع الرسمية.</p><p>لم تُضمّن أرقام التواصل أو الرسائل أو ملاحظات المبيعات الخاصة في هذه الحزمة. يلزم اعتماد الجهة وتفاصيل التشغيل والعملات والدفع قبل نشر أي تدريب حقيقي.</p></section></main><script>
const country=document.getElementById('country'),sport=document.getElementById('sport'),query=document.getElementById('query'),cards=[...document.querySelectorAll('article')];
function filter(){let count=0;for(const card of cards){const show=(!country.value||card.dataset.country===country.value)&&(!sport.value||card.dataset.sport===sport.value)&&(!query.value.trim()||card.dataset.search.includes(query.value.trim().toLowerCase()));card.hidden=!show;if(show)count++;}document.getElementById('count').textContent=`عرض ${count} جهة · ${count*3} تدريبًا مقترحًا`;document.querySelector('.empty').hidden=count!==0;}
for(const control of [country,sport,query])control.addEventListener('input',filter);document.getElementById('reset').addEventListener('click',()=>{country.value='';sport.value='';query.value='';filter()});filter();
</script></body></html>'''
page=page.replace('<option value="">كل الرياضات</option>','<option value="">كل الرياضات</option>'+options).replace('<section class="grid" aria-label="المقترحات"></section>','<section class="grid" aria-label="المقترحات">'+''.join(cards)+'</section>')
(out/'catalog-preview.html').write_text(page)
(out/'hagzz.svg').write_bytes((root/'public/assetsAdmin/catalog/hagzz.svg').read_bytes())
with zipfile.ZipFile(out/'Hagzz-Egypt-Qatar-Catalog-Proposals.zip','w',zipfile.ZIP_DEFLATED) as z:
    for name in ['catalog-preview.html','hagzz.svg','egypt-qatar-training-proposals.csv','egypt-qatar-demo-sessions.csv','README.md']:
        z.write(out/name,name)
    z.write(root/'resources/catalog/egypt-qatar-proposals.json','egypt-qatar-proposals.json')
print(out/'Hagzz-Egypt-Qatar-Catalog-Proposals.zip')
